/**
 * generated by stackra gen from the consumed manifests' settings at user scope (notifications:
 * messages, `extends Settings({ scopes })` in its module root) — do not edit
 * Purpose: the typed setting keys this app renders (`Settings.messages.orderUpdates`) with their
 *          metadata and labels, and the generated user page per module (`SettingsPages.messages`).
 * Boundary: data; values are read and written through the settings actions at run time by
 *           `SettingsForm` from @stackra/settings/native. Labels are the producer's derived keys
 *           (`messages::settings.messages.<field>`). Nothing here is a value.
 * Runtime: isomorphic
 */
import { SettingScope, SettingType, settingKeys, settingsPage } from "@stackra/settings";
import { I18n } from "#stackra/i18n";

/** `<module>.<field>` → type, default, scopes, label; the same shape as the console's. */
export const Settings = settingKeys({
  messages: {
    orderUpdates: {
      type: SettingType.Boolean,
      default: true,
      scopes: [SettingScope.User],
      label: I18n.messages.settings.messages.order_updates,
    },
    orderReceipts: {
      type: SettingType.Boolean,
      default: true,
      scopes: [SettingScope.User],
      label: I18n.messages.settings.messages.order_receipts,
    },
    productUpdates: {
      type: SettingType.Boolean,
      default: false,
      scopes: [SettingScope.User],
      label: I18n.messages.settings.messages.product_updates,
    },
    marketing: {
      type: SettingType.Boolean,
      default: false,
      scopes: [SettingScope.User],
      label: I18n.messages.settings.messages.marketing,
    },
  },
});

/** One generated page per module this app renders; user-scoped, so no permission gates it. */
export const SettingsPages = {
  messages: settingsPage("messages", { scope: SettingScope.User }),
} as const;
